from datetime import datetime
from typing import Dict, List, Optional, Tuple

class Scheduler:
    def __init__(self) -> None:
        self.appointments: Dict[int, Dict[str, any]] = {}  # id -> {patient, doctor, start, end}
        self.next_id = 1
        # Track patient's upcoming appointments for constraint checking
        self.patient_appointments: Dict[str, List[int]] = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        # Requirement 3: Booking an appointment that starts before `now` raises ValueError
        if start < now:
            raise ValueError("Appointment cannot start before current time")

        # Requirement 2: A patient can have at most one upcoming appointment
        # Check if patient already has an upcoming appointment (start >= now)
        if patient in self.patient_appointments:
            for appt_id in self.patient_appointments[patient]:
                appt = self.appointments[appt_id]
                if appt["start"] >= now:
                    raise ValueError("Patient already has an upcoming appointment")

        # Requirement 4: Booking an appointment that overlaps another appointment of the same doctor
        # Check for overlapping appointments with the same doctor
        for appt_id, appt in self.appointments.items():
            if appt["doctor"] == doctor:
                # Two appointments overlap if: start1 < end2 AND start2 < end1
                # Since touching appointments are allowed (one ends when another starts), 
                # we use strict inequalities for overlap detection
                if start < appt["end"] and appt["start"] < end:
                    raise ValueError("Doctor is not available during this time")

        # Create new appointment
        appointment_id = self.next_id
        self.next_id += 1

        self.appointments[appointment_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end
        }

        # Update patient's appointment list
        if patient not in self.patient_appointments:
            self.patient_appointments[patient] = []
        self.patient_appointments[patient].append(appointment_id)

        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an appointment."""
        if appointment_id not in self.appointments:
            return  # No-op if appointment doesn't exist

        appointment = self.appointments[appointment_id]

        # Remove from patient's appointments list
        patient = appointment["patient"]
        if patient in self.patient_appointments:
            if appointment_id in self.patient_appointments[patient]:
                self.patient_appointments[patient].remove(appointment_id)
                # Clean up empty lists
                if not self.patient_appointments[patient]:
                    del self.patient_appointments[patient]

        # Remove the appointment
        del self.appointments[appointment_id]

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        # Check for overlapping appointments with the same doctor
        for appt in self.appointments.values():
            if appt["doctor"] == doctor:
                # Two appointments overlap if: start1 < end2 AND start2 < end1
                if start < appt["end"] and appt["start"] < end:
                    return False

        return True
